steps.command:
sbx run <<'EOF'
cd /workspace
sqlite3 oewn.sqlite "
SELECT 'words_dupe_wordid', COUNT(*) FROM (SELECT wordid FROM words GROUP BY wordid HAVING COUNT(*)>1);
SELECT 'words_distinct_ids', COUNT(DISTINCT wordid), COUNT(*) FROM words;
SELECT 'senses_missing_synset', COUNT(*) FROM senses s LEFT JOIN synsets y ON s.synsetid=y.synsetid WHERE y.synsetid IS NULL;
SELECT 'senses_missing_word', COUNT(*) FROM senses s LEFT JOIN words w ON s.wordid=w.wordid WHERE w.wordid IS NULL;
SELECT 'distinct_word_synset_pairs', COUNT(*) FROM (SELECT wordid,synsetid FROM senses GROUP BY wordid,synsetid);
SELECT 'senses_dupe_full', COUNT(*) FROM (SELECT wordid,synsetid,COUNT(*) c FROM senses GROUP BY wordid,synsetid HAVING c>1 LIMIT 5);
"
EOF
